data.frag_shader:
#define STANDARD
#define USE_CLEARCOAT
#define USE_UV

#ifdef PHYSICAL
#define IOR
#define SPECULAR
#endif
varying vec2 vUvOverlapped;
varying vec2 vUvPacked;
uniform vec3 diffuse;
uniform vec3 emissive;
uniform float roughness;
uniform float metalness;
uniform float opacity;
uniform float hiddenness;
uniform sampler2D u_numberMap;
uniform sampler2D u_faceMap;
uniform vec3 number;
uniform vec3 numberOutline;
uniform float dissolve;
uniform vec3 face;
uniform float numberOpacity;
uniform float outlineOpacity;

#ifdef IOR
uniform float ior;
#endif

#ifdef SPECULAR
uniform float specularIntensity;
uniform vec3 specularColor;

#ifdef USE_SPECULARINTENSITYMAP
uniform sampler2D specularIntensityMap;
#endif

#ifdef USE_SPECULARCOLORMAP
uniform sampler2D specularColorMap;
#endif
#endif

#ifdef USE_CLEARCOAT
uniform float clearcoat;
uniform float clearcoatRoughness;
#endif

#ifdef USE_SHEEN
uniform vec3 sheenColor;
uniform float sheenRoughness;

#ifdef USE_SHEENCOLORMAP
uniform sampler2D sheenColorMap;
#endif

#ifdef USE_SHEENROUGHNESSMAP
uniform sampler2D sheenRoughnessMap;
#endif
#endif

varying vec3 vViewPosition;

#include <common>
#include <packing>
#include <dithering_pars_fragment>
#include <color_pars_fragment>
#include <uv_pars_fragment>
#include <uv2_pars_fragment>
#include <map_pars_fragment>
#include <alphamap_pars_fragment>
#include <alphatest_pars_fragment>
#include <aomap_pars_fragment>
#include <lightmap_pars_fragment>
#include <emissivemap_pars_fragment>
#include <bsdfs>
#include <cube_uv_reflection_fragment>
#include <envmap_common_pars_fragment>
#include <envmap_physical_pars_fragment>
#include <fog_pars_fragment>
#include <lights_pars_begin>
#include <normal_pars_fragment>
#include <lights_physical_pars_fragment>
#include <transmission_pars_fragment>
#include <shadowmap_pars_fragment>
#include <bumpmap_pars_fragment>
#include <normalmap_pars_fragment>
#include <clearcoat_pars_fragment>
#include <roughnessmap_pars_fragment>
#include <metalnessmap_pars_fragment>
#include <logdepthbuf_pars_fragment>
#include <clipping_planes_pars_fragment>

float rand2(vec2 c){
    return fract(sin(dot(c.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

float noise(vec2 p, float freq ){
    float unit = 128./freq;
    vec2 ij = floor(p/unit);
    vec2 xy = mod(p,unit)/unit;
    //xy = 3.*xy*xy-2.*xy*xy*xy;
    xy = .5*(1.-cos(3.1415*xy));
    float a = rand2((ij+vec2(0.,0.)));
    float b = rand2((ij+vec2(1.,0.)));
    float c = rand2((ij+vec2(0.,1.)));
    float d = rand2((ij+vec2(1.,1.)));
    float x1 = mix(a, b, xy.x);
    float x2 = mix(c, d, xy.x);
    return mix(x1, x2, xy.y);
}

float pNoise(vec2 p, int res){
    float persistance = .5;
    float n = 0.;
    float normK = 0.;
    float f = 4.;
    float amp = 2.;
    int iCount = 0;
    for (int i = 0; i<50; i++){
        n+=amp*noise(p, f);
        f*=2.;
        normK+=amp;
        amp*=persistance;
        if (iCount == res) break;
        iCount++;
    }
    float nf = n/normK;
    return nf*nf*nf*nf;
}

void main(){
    if( clamp(pNoise( gl_FragCoord.xy, 1), 0.0, 1.0 ) > 1.0-dissolve ) discard;
    
    #include <clipping_planes_fragment>
    
    vec4 diffuseColor = vec4( diffuse, opacity );
    ReflectedLight reflectedLight = ReflectedLight( vec3( 0.0 ), vec3( 0.0 ), vec3( 0.0 ), vec3( 0.0 ) );
    vec3 totalEmissiveRadiance = emissive;
    
    #include <logdepthbuf_fragment>
    #include <map_fragment>
    

    vec4 u_faceMapIn = texture2D( u_faceMap, vUvOverlapped );
    // adjust color of face
    u_faceMapIn.rgb *= face;
    // overlay face map over diffuse color or map
    diffuseColor.rgb = mix(diffuseColor.rgb, u_faceMapIn.rgb, u_faceMapIn.a);
    
    vec4 u_numberMapIn = texture2D( u_numberMap, vUv );
    // adjust color of numbers
    float numberColAlpha = clamp(u_numberMapIn.r * outlineOpacity + u_numberMapIn.g * numberOpacity, 0.0, 1.0);
    u_numberMapIn.rgb = (u_numberMapIn.r * outlineOpacity * numberOutline + u_numberMapIn.g * numberOpacity * number);
    
    // overlay number map and apply hiddenness
    diffuseColor.rgb = mix(diffuseColor.rgb, u_numberMapIn.rgb, u_numberMapIn.a * numberColAlpha * (1.0 - hiddenness));

    #include <color_fragment>
    #include <alphamap_fragment>
    #include <alphatest_fragment>
    #include <roughnessmap_fragment>

    // clipped from metalness_fragment
    float metalnessFactor = metalness;

    #ifdef USE_METALNESSMAP

    vec4 texelMetalness = texture2D( metalnessMap, vUv );

    metalnessFactor *=  clamp(texelMetalness.r * outlineOpacity + texelMetalness.g * numberOpacity, 0.0, 1.0-hiddenness);

    #endif

    #include <normal_fragment_begin>
    #include <normal_fragment_maps>
    #include <clearcoat_normal_fragment_begin>
    #include <clearcoat_normal_fragment_maps>
    #include <emissivemap_fragment>
    
    // accumulation
    #include <lights_physical_fragment>
    #include <lights_fragment_begin>
    #include <lights_fragment_maps>
    #include <lights_fragment_end>
    
    // modulation
    #include <aomap_fragment>
    
    vec3 totalDiffuse = reflectedLight.directDiffuse + reflectedLight.indirectDiffuse;
    vec3 totalSpecular = reflectedLight.directSpecular + reflectedLight.indirectSpecular;
    
    #include <transmission_fragment>
    
    vec3 outgoingLight = totalDiffuse + totalSpecular + totalEmissiveRadiance;
    
    #ifdef USE_SHEEN
    
    // Sheen energy compensation approximation calculation can be found at the end of
    // https://drive.google.com/file/d/1T0D1VSyR4AllqIJTQAraEIzjlb5h4FKH/view?usp=sharing
    float sheenEnergyComp = 1.0 - 0.157 * max3( material.sheenColor );
    
    outgoingLight = outgoingLight * sheenEnergyComp + sheenSpecular;
    
    #endif
    
    #ifdef USE_CLEARCOAT
    
    float dotNVcc = saturate( dot( geometry.clearcoatNormal, geometry.viewDir ) );
    
    vec3 Fcc = F_Schlick( material.clearcoatF0, material.clearcoatF90, dotNVcc );
    
    outgoingLight = outgoingLight * ( 1.0 - material.clearcoat * Fcc ) + clearcoatSpecular * material.clearcoat;
    
    #endif
    
    #include <output_fragment>
    #include <tonemapping_fragment>
    #include <encodings_fragment>
    #include <fog_fragment>
    #include <premultiplied_alpha_fragment>
    #include <dithering_fragment>
    
}

