data.frag_shader:
// version 2.0
#define PHONG
#define USE_UV
#define USE_BUMPMAP
#define USE_EMISSIVEMAP
#define USE_SPECULARMAP

varying vec2 vUvOverlapped;
varying vec2 vUvPacked;

uniform float dissolve;
uniform float hiddenness;
uniform float opacity;
uniform float shininess;
uniform vec3 diffuse;
uniform vec3 emissive;
uniform vec3 outlineEmissive;
uniform vec3 number;
uniform vec3 outline;
uniform vec3 specular;

uniform sampler2D u_numberBumpMap;
uniform sampler2D u_numberEmissiveMap;
uniform sampler2D u_numberMap;
uniform sampler2D u_numberSpecularMap;
uniform sampler2D u_outlineBumpMap;
uniform sampler2D u_outlineEmissiveMap;
uniform sampler2D u_outlineMap;
uniform sampler2D u_outlineSpecularMap;


#include <common>
#include <packing>
#include <dithering_pars_fragment>
#include <color_pars_fragment>
#include <uv_pars_fragment>
#include <uv2_pars_fragment>
#include <map_pars_fragment>
#include <alphamap_pars_fragment>
#include <alphatest_pars_fragment>
#include <aomap_pars_fragment>
#include <lightmap_pars_fragment>
#include <emissivemap_pars_fragment>
#include <envmap_common_pars_fragment>
#include <envmap_pars_fragment>
#include <cube_uv_reflection_fragment>
#include <fog_pars_fragment>
#include <bsdfs>
#include <lights_pars_begin>
#include <normal_pars_fragment>
#include <lights_phong_pars_fragment>
#include <shadowmap_pars_fragment>


// clipped from bumpmap_pars_fragment
#ifdef USE_BUMPMAP
uniform sampler2D bumpMap;
uniform float bumpScale;

// Bump Mapping Unparametrized Surfaces on the GPU by Morten S. Mikkelsen
// https://mmikk.github.io/papers3d/mm_sfgrad_bump.pdf

// Evaluate the derivative of the height w.r.t. screen-space using forward differencing (listing 2)

vec2 dHdxy_fwd() {
    // apply hiddenness to bump map
    vec2 dSTdx = dFdx(vUv);
    vec2 dSTdy = dFdy(vUv);
    vec2 dSTdxP = dFdx(vUvPacked);
    vec2 dSTdyP = dFdy(vUvPacked);
    vec2 dSTdxO = dFdx(vUvOverlapped);
    vec2 dSTdyO = dFdy(vUvOverlapped);

    float tex1 = 0.5;
    float tex2 = 0.5;
    float tex3 = 0.5;

    tex1 = mix(tex1, texture2D(bumpMap, vUvPacked).x, texture2D(bumpMap, vUvPacked).a) ;
    tex2 = mix(tex2, texture2D(bumpMap, vUvPacked + dSTdxP).x, texture2D(bumpMap, vUvPacked).a);
    tex3 = mix(tex3, texture2D(bumpMap, vUvPacked + dSTdyP).x, texture2D(bumpMap, vUvPacked).a);

    tex1 = mix(tex1, texture2D(u_outlineBumpMap, vUvOverlapped).x, texture2D(u_outlineBumpMap, vUvOverlapped).a) ;
    tex2 = mix(tex2, texture2D(u_outlineBumpMap, vUvOverlapped + dSTdxP).x, texture2D(u_outlineBumpMap, vUvOverlapped).a);
    tex3 = mix(tex3, texture2D(u_outlineBumpMap, vUvOverlapped + dSTdyP).x, texture2D(u_outlineBumpMap, vUvOverlapped).a);

    if(abs(texture2D(u_numberBumpMap, vUv).x - 0.5) > 0.1)
    {
        tex1 = mix(tex1, texture2D(u_numberBumpMap, vUv).x, texture2D(u_numberBumpMap, vUv).a * (1.0 - hiddenness));
        tex2 = mix(tex2, texture2D(u_numberBumpMap, vUv + dSTdx).x, texture2D(u_numberBumpMap, vUv + dSTdx).a * (1.0 - hiddenness));
        tex3 = mix(tex3, texture2D(u_numberBumpMap, vUv + dSTdy).x, texture2D(u_numberBumpMap, vUv + dSTdy).a * (1.0 - hiddenness));
    }

