    tex2 = mix(tex2, texture2D(u_outlineBumpMap, vUvOverlapped + dSTdxP).x, texture2D(u_outlineBumpMap, vUvOverlapped).a);
    tex3 = mix(tex3, texture2D(u_outlineBumpMap, vUvOverlapped + dSTdyP).x, texture2D(u_outlineBumpMap, vUvOverlapped).a);

    if(abs(texture2D(u_numberBumpMap, vUv).x - 0.5) > 0.1)
    {
        tex1 = mix(tex1, texture2D(u_numberBumpMap, vUv).x, texture2D(u_numberBumpMap, vUv).a * (1.0 - hiddenness));
        tex2 = mix(tex2, texture2D(u_numberBumpMap, vUv + dSTdx).x, texture2D(u_numberBumpMap, vUv + dSTdx).a * (1.0 - hiddenness));
        tex3 = mix(tex3, texture2D(u_numberBumpMap, vUv + dSTdy).x, texture2D(u_numberBumpMap, vUv + dSTdy).a * (1.0 - hiddenness));
    }

    float Hll = bumpScale * tex1;
    float dBx = bumpScale * tex2 - Hll;
    float dBy = bumpScale * tex3 - Hll;

    return vec2(dBx, dBy);

}

vec3 perturbNormalArb( vec3 surf_pos, vec3 surf_norm, vec2 dHdxy, float faceDirection ) {

    // Workaround for Adreno 3XX dFd*( vec3 ) bug. See #9988

    vec3 vSigmaX = vec3( dFdx( surf_pos.x ), dFdx( surf_pos.y ), dFdx( surf_pos.z ) );
    vec3 vSigmaY = vec3( dFdy( surf_pos.x ), dFdy( surf_pos.y ), dFdy( surf_pos.z ) );
    vec3 vN = surf_norm;		// normalized

    vec3 R1 = cross( vSigmaY, vN );
    vec3 R2 = cross( vN, vSigmaX );

    float fDet = dot( vSigmaX, R1 ) * faceDirection;

    vec3 vGrad = sign( fDet ) * ( dHdxy.x * R1 + dHdxy.y * R2 );
    return normalize( abs( fDet ) * surf_norm - vGrad );

}
#endif

#include <normalmap_pars_fragment>
#include <clearcoat_pars_fragment>
#include <roughnessmap_pars_fragment>
#include <metalnessmap_pars_fragment>
#include <logdepthbuf_pars_fragment>
#include <clipping_planes_pars_fragment>

float rand2(vec2 c){
	return fract(sin(dot(c.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

float noise(vec2 p, float freq ){
	float unit = 128./freq;
	vec2 ij = floor(p/unit);
	vec2 xy = mod(p,unit)/unit;
	//xy = 3.*xy*xy-2.*xy*xy*xy;
	xy = .5*(1.-cos(3.1415*xy));
	float a = rand2((ij+vec2(0.,0.)));
	float b = rand2((ij+vec2(1.,0.)));
	float c = rand2((ij+vec2(0.,1.)));
	float d = rand2((ij+vec2(1.,1.)));
	float x1 = mix(a, b, xy.x);
	float x2 = mix(c, d, xy.x);
	return mix(x1, x2, xy.y);
}

float pNoise(vec2 p, int res){
	float persistance = .5;
	float n = 0.;
	float normK = 0.;
	float f = 4.;
	float amp = 2.;
	int iCount = 0;
	for (int i = 0; i<50; i++){
		n+=amp*noise(p, f);
		f*=2.;
		normK+=amp;
		amp*=persistance;
		if (iCount == res) break;
		iCount++;
	}
	float nf = n/normK;
	return nf*nf*nf*nf;
}

void main(){
    if( clamp(pNoise( gl_FragCoord.xy, 1), 0.0, 1.0 ) > 1.0-dissolve ) discard;

    #include <clipping_planes_fragment>

    vec4 diffuseColor = vec4( diffuse, opacity );
    ReflectedLight reflectedLight = ReflectedLight( vec3( 0.0 ), vec3( 0.0 ), vec3( 0.0 ), vec3( 0.0 ) );
    vec3 totalEmissiveRadiance = emissive;

    #include <logdepthbuf_fragment>
    
#ifdef USE_MAP

	vec4 sampledDiffuseColor = texture2D( map, vUvPacked );

	#ifdef DECODE_VIDEO_TEXTURE

		// inline sRGB decode (TODO: Remove this code when https://crbug.com/1256340 is solved)

		sampledDiffuseColor = vec4( mix( pow( sampledDiffuseColor.rgb * 0.9478672986 + vec3( 0.0521327014 ), vec3( 2.4 ) ), sampledDiffuseColor.rgb * 0.0773993808, vec3( lessThanEqual( sampledDiffuseColor.rgb, vec3( 0.04045 ) ) ) ), sampledDiffuseColor.w );

	#endif

	diffuseColor *= sampledDiffuseColor;

#endif

vec4 u_outlineMapIn = texture2D( u_outlineMap, vUvOverlapped );
// adjust color of outline
u_outlineMapIn.rgb *= outline;
// overlay outline map over diffuse color or map
diffuseColor.rgb = mix(diffuseColor.rgb, u_outlineMapIn.rgb, u_outlineMapIn.a);

vec4 u_numberMapIn = texture2D( u_numberMap, vUv );
// adjust color of numbers
u_numberMapIn.rgb *= number;
// overlay number map and apply hiddenness
diffuseColor.rgb = mix(diffuseColor.rgb, u_numberMapIn.rgb, u_numberMapIn.a * (1.0 - hiddenness));



    #include <color_fragment>
    #include <alphamap_fragment>
    #include <alphatest_fragment>

    float roughnessFactor = roughness;
    #ifdef USE_ROUGHNESSMAP
        vec4 texelRoughness= texture2D(roughnessMap, vUvPacked);
        vec4 texelOutlineRoughness = texture2D(u_outlineRoughnessMap, vUvOverlapped);
        vec4 texelNumberRoughness = texture2D(u_numberRoughnessMap, vUv);

        roughnessFactor = mix(roughness, texelRoughness.g * roughness, texelRoughness.a);
        roughnessFactor = mix(roughnessFactor, texelOutlineRoughness.g, texelOutlineRoughness.a);
        roughnessFactor = mix(roughnessFactor, texelNumberRoughness.g, texelNumberRoughness.a * (1.0 - hiddenness));

    #endif

    // clipped from metalness_fragment
    float metalnessFactor = metalness;

    #ifdef USE_METALNESSMAP

        vec4 texelMetalness= texture2D(metalnessMap, vUvPacked);
        vec4 texelOutlineMetalness = texture2D(u_outlineMetalnessMap, vUvOverlapped);
        vec4 texelNumberMetalness = texture2D(u_numberMetalnessMap, vUv);

        metalnessFactor = mix(metalness, texelMetalness.r * metalness, texelMetalness.a);
        metalnessFactor = mix(metalnessFactor, texelOutlineMetalness.r, texelOutlineMetalness.a);
        metalnessFactor = mix(metalnessFactor, texelNumberMetalness.r, texelNumberMetalness.a * (1.0 - hiddenness));


    #endif

    #include <normal_fragment_begin>
    #include <normal_fragment_maps>
    #include <clearcoat_normal_fragment_begin>
    #include <clearcoat_normal_fragment_maps>

    
#ifdef USE_EMISSIVEMAP
        vec4 emissiveColor = texture2D( emissiveMap, vUvPacked );
        vec4 u_outlineEmissiveMapIn = texture2D(u_outlineEmissiveMap, vUvOverlapped);
        vec4 u_numberEmissiveMapIn = texture2D(u_numberEmissiveMap, vUv);

        // overlay number map and apply hiddenness
        totalEmissiveRadiance.rgb = mix(emissive.rgb, emissiveColor.rgb * emissive.rgb, emissiveColor.a );
        totalEmissiveRadiance.rgb = mix(totalEmissiveRadiance.rgb, u_outlineEmissiveMapIn.rgb * outlineEmissive.rgb, u_outlineEmissiveMapIn.a);
        totalEmissiveRadiance.rgb = mix(totalEmissiveRadiance.rgb, u_numberEmissiveMapIn.rgb, u_numberEmissiveMapIn.a * (1.0 - hiddenness));

#endif

    // accumulation
    PhysicalMaterial material;
    material.diffuseColor = diffuseColor.rgb * ( 1.0 - metalnessFactor );
    vec3 dxy = max( abs( dFdx( geometryNormal ) ), abs( dFdy( geometryNormal ) ) );
    float geometryRoughness = max( max( dxy.x, dxy.y ), dxy.z );
    material.roughness = max( roughnessFactor, 0.0525 );// 0.0525 corresponds to the base mip of a 256 cubemap.
    material.roughness += geometryRoughness;
    material.roughness = min( material.roughness, 1.0 );
    #ifdef IOR
        material.ior = ior;
        #ifdef USE_SPECULAR
            float specularIntensityFactor = specularIntensity;
            vec3 specularColorFactor = specularColor;
            #ifdef USE_SPECULAR_COLORMAP
                specularColorFactor *= texture2D( specularColorMap, vSpecularColorMapUv ).rgb;
            #endif
            #ifdef USE_SPECULAR_INTENSITYMAP
                specularIntensityFactor *= texture2D( specularIntensityMap, vSpecularIntensityMapUv ).a;
            #endif
            material.specularF90 = mix( specularIntensityFactor, 1.0, metalnessFactor );
        #else
            float specularIntensityFactor = 1.0;
            vec3 specularColorFactor = vec3( 1.0 );
            material.specularF90 = 1.0;
        #endif
        material.specularColor = mix( min( pow2( ( material.ior - 1.0 ) / ( material.ior + 1.0 ) ) * specularColorFactor, vec3( 1.0 ) ) * specularIntensityFactor, diffuseColor.rgb, metalnessFactor );
    #else
        material.specularColor = mix( vec3( 0.04 ), diffuseColor.rgb, metalnessFactor );
        material.specularF90 = 1.0;
    #endif
    #ifdef USE_CLEARCOAT
        material.clearcoat = clearcoat;
        material.clearcoatRoughness = clearcoatRoughness;
        material.clearcoatF0 = vec3( 0.04 );
        material.clearcoatF90 = 1.0;
        #ifdef USE_CLEARCOATMAP
            //material.clearcoat *= texture2D( clearcoatMap, vUvPacked ).x;
            vec4 texelClearcoat = texture2D(clearcoatMap, vUvPacked);
            vec4 texelNumberClearcoat = texture2D(u_numberClearcoatMap, vUv);

            if(texelClearcoat.a > 0.0) {
                material.clearcoat =  mix(texelClearcoat.r * clearcoat, texelNumberClearcoat.r, texelNumberClearcoat.a * (1.0 - hiddenness));
            } else {
                material.clearcoat =  mix(clearcoat, texelNumberClearcoat.r, texelNumberClearcoat.a * (1.0 - hiddenness));
            }
        #endif
        #ifdef USE_CLEARCOAT_ROUGHNESSMAP
            //material.clearcoatRoughness *= texture2D( clearcoatRoughnessMap, vUvPacked ).y;
            vec4 texelClearcoatRoughness = texture2D(clearcoatRoughnessMap, vUvPacked);
            vec4 texelNumberClearcoatRoughness = texture2D(u_numberClearcoatRoughnessMap, vUv);

            if(texelClearcoatRoughness.a > 0.0) {
                material.clearcoatRoughness =  mix(texelClearcoatRoughness.g * clearcoatRoughness, texelNumberClearcoatRoughness.g, texelNumberClearcoatRoughness.a * (1.0 - hiddenness));
            } else {
                material.clearcoatRoughness =  mix(clearcoatRoughness, texelNumberClearcoatRoughness.g, texelNumberClearcoatRoughness.a * (1.0 - hiddenness));
            }
        #endif
        material.clearcoat = saturate( material.clearcoat ); // Burley clearcoat model
        material.clearcoatRoughness = max( material.clearcoatRoughness, 0.0525 );
        material.clearcoatRoughness += geometryRoughness;
        material.clearcoatRoughness = min( material.clearcoatRoughness, 1.0 );
    #endif
    #ifdef USE_IRIDESCENCE
        material.iridescence = iridescence;
        material.iridescenceIOR = iridescenceIOR;
        #ifdef USE_IRIDESCENCEMAP
            material.iridescence *= texture2D( iridescenceMap, vIridescenceMapUv ).r;
        #endif
        #ifdef USE_IRIDESCENCE_THICKNESSMAP
            material.iridescenceThickness = (iridescenceThicknessMaximum - iridescenceThicknessMinimum) * texture2D( iridescenceThicknessMap, vIridescenceThicknessMapUv ).g + iridescenceThicknessMinimum;
        #else
            material.iridescenceThickness = iridescenceThicknessMaximum;
        #endif
    #endif
    #ifdef USE_SHEEN
        material.sheenColor = sheenColor;
        #ifdef USE_SHEEN_COLORMAP
            material.sheenColor *= texture2D( sheenColorMap, vUvPacked ).rgb;
        #endif
        material.sheenRoughness = clamp( sheenRoughness, 0.07, 1.0 );
        #ifdef USE_SHEEN_ROUGHNESSMAP
            material.sheenRoughness *= texture2D( sheenRoughnessMap, vUvPacked ).a;
        #endif
    #endif



    #include <lights_fragment_begin>
    #include <lights_fragment_maps>
    #include <lights_fragment_end>

    // modulation
    #include <aomap_fragment>

    vec3 totalDiffuse = reflectedLight.directDiffuse + reflectedLight.indirectDiffuse;
    vec3 totalSpecular = reflectedLight.directSpecular + reflectedLight.indirectSpecular;

    #include <transmission_fragment>

    vec3 outgoingLight = totalDiffuse + totalSpecular + totalEmissiveRadiance;

    #ifdef USE_SHEEN

    // Sheen energy compensation approximation calculation can be found at the end of
    // https://drive.google.com/file/d/1T0D1VSyR4AllqIJTQAraEIzjlb5h4FKH/view?usp=sharing
    float sheenEnergyComp = 1.0 - 0.157 * max3( material.sheenColor );

    outgoingLight = outgoingLight * sheenEnergyComp + sheenSpecular;

    #endif

    #ifdef USE_CLEARCOAT

    float dotNVcc = saturate( dot( geometry.clearcoatNormal, geometry.viewDir ) );

    vec3 Fcc = F_Schlick( material.clearcoatF0, material.clearcoatF90, dotNVcc );

    outgoingLight = outgoingLight * ( 1.0 - material.clearcoat * Fcc ) + clearcoatSpecular * material.clearcoat;

    #endif

    #include <output_fragment>
    #include <tonemapping_fragment>
    #include <encodings_fragment>
    #include <fog_fragment>
    #include <premultiplied_alpha_fragment>
    #include <dithering_fragment>

}

