data.frag_shader:
uniform vec3 diffuse;
uniform vec3 emissive;
uniform vec3 specular;
uniform float shininess;
uniform float opacity;
uniform float hiddenness;
varying vec2 vUvOverlapped;
varying vec2 vUvPacked;
uniform float time;
uniform vec3 color1;
uniform vec3 color2;
uniform vec3 color3;
uniform sampler2D u_colorMap;
uniform float dissolve;

#include <common>
#include <packing>
#include <dithering_pars_fragment>
#include <color_pars_fragment>
#include <uv_pars_fragment>
#include <uv2_pars_fragment>
#include <map_pars_fragment>
#include <alphamap_pars_fragment>
#include <alphatest_pars_fragment>
#include <aomap_pars_fragment>
#include <lightmap_pars_fragment>
#include <emissivemap_pars_fragment>
#include <envmap_common_pars_fragment>
#include <envmap_pars_fragment>
#include <cube_uv_reflection_fragment>
#include <fog_pars_fragment>
#include <bsdfs>
#include <lights_pars_begin>
#include <normal_pars_fragment>
#include <lights_phong_pars_fragment>
#include <shadowmap_pars_fragment>
#include <bumpmap_pars_fragment>
#include <normalmap_pars_fragment>
#include <specularmap_pars_fragment>
#include <logdepthbuf_pars_fragment>
#include <clipping_planes_pars_fragment>
float rand2(vec2 c){
	return fract(sin(dot(c.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

float noise(vec2 p, float freq ){
	float unit = 128./freq;
	vec2 ij = floor(p/unit);
	vec2 xy = mod(p,unit)/unit;
	//xy = 3.*xy*xy-2.*xy*xy*xy;
	xy = .5*(1.-cos(3.1415*xy));
	float a = rand2((ij+vec2(0.,0.)));
	float b = rand2((ij+vec2(1.,0.)));
	float c = rand2((ij+vec2(0.,1.)));
	float d = rand2((ij+vec2(1.,1.)));
	float x1 = mix(a, b, xy.x);
	float x2 = mix(c, d, xy.x);
	return mix(x1, x2, xy.y);
}

float pNoise(vec2 p, int res){
	float persistance = .5;
	float n = 0.;
	float normK = 0.;
	float f = 4.;
	float amp = 2.;
	int iCount = 0;
	for (int i = 0; i<50; i++){
		n+=amp*noise(p, f);
		f*=2.;
		normK+=amp;
		amp*=persistance;
		if (iCount == res) break;
		iCount++;
	}
	float nf = n/normK;
	return nf*nf*nf*nf;
}

void main(){
	if( clamp(pNoise( gl_FragCoord.xy, 1), 0.0, 1.0 ) > 1.0-dissolve ) discard;
	#include <clipping_planes_fragment>
	vec4 diffuseColor = vec4( diffuse, opacity );
	ReflectedLight reflectedLight = ReflectedLight( vec3( 0.0 ), vec3( 0.0 ), vec3( 0.0 ), vec3( 0.0 ) );
	vec3 totalEmissiveRadiance = emissive;

	#include <logdepthbuf_fragment>
	#include <color_fragment>
	#include <alphamap_fragment>
	#include <alphatest_fragment>

  vec3 numberColIn = texture2D( map, vUv ).rgb;
  vec3 numberCol = (numberColIn.r * color1 + numberColIn.g * color2 + numberColIn.b * color3);
  float numberColAlpha = clamp(numberColIn.r + numberColIn.g + numberColIn.b, 0.0, 1.0) * (1.0 - hiddenness);
  float numberColInvAlpha = 1.0 - numberColAlpha;

  vec3 u_colorMapIn = texture2D( u_colorMap, vUvOverlapped ).rgb;
  vec3 u_colorMap = (u_colorMapIn.r * color1 + u_colorMapIn.g * color2 + u_colorMapIn.b * color3);

  vec4 color = vec4(numberCol * numberColAlpha + u_colorMap * numberColInvAlpha, 1.0);
  diffuseColor *= color;

  float specularStrength;
  vec4 texelSpecular = texture2D(specularMap, vUvOverlapped);
  specularStrength = texelSpecular.r;
  specularStrength = specularStrength * numberColInvAlpha + 0.7 * numberColAlpha;
  specularStrength *= (sin(time * 1.25) + 1.0) / 4.0 + 0.5;

	#include <normal_fragment_begin>
	#include <normal_fragment_maps>
	#include <emissivemap_fragment>
	// accumulation
	#include <lights_phong_fragment>
	#include <lights_fragment_begin>
	#include <lights_fragment_maps>
	#include <lights_fragment_end>
	vec3 outgoingLight = reflectedLight.directDiffuse + reflectedLight.indirectDiffuse + reflectedLight.directSpecular + reflectedLight.indirectSpecular + totalEmissiveRadiance;
  gl_FragColor = vec4( outgoingLight, diffuseColor.a );
	#include <envmap_fragment>
	#include <output_fragment>
	#include <tonemapping_fragment>
	#include <encodings_fragment>
	#include <fog_fragment>
	#include <premultiplied_alpha_fragment>
	#include <dithering_fragment>
}

